using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using TajaFarm.Api.Data;using TajaFarm.Api.Models;
namespace TajaFarm.Api.Controllers;[ApiController][Route("api/cart")]
public class CartController:BaseController{
 [HttpGet]public async Task<IActionResult> Get([FromServices]AppDbContext db){var r=RequireUser(out var t);if(r is not null)return r;var rows=await db.CartItems.Where(c=>c.UserId==t!.Id).Join(db.Products,c=>c.ProductId,p=>p.Id,(c,p)=>new{c.ProductId,c.Qty,p}).ToListAsync();return Ok(rows.Select(x=>new{x.ProductId,x.Qty,product=ProductDto(x.p)}));}
 [HttpPost("add")]public async Task<IActionResult> Add(CartAddRequest req,[FromServices]AppDbContext db){var r=RequireRole("customer",out var t);if(r is not null)return r;if(req.Qty<=0)return BadRequest(new{error="Quantity must be greater than 0"});var p=await db.Products.FindAsync(req.ProductId);if(p is null)return NotFound(new{error="Product not found"});if(req.Qty>p.Stock)return BadRequest(new{error="Not enough stock"});var c=await db.CartItems.FirstOrDefaultAsync(x=>x.UserId==t!.Id&&x.ProductId==req.ProductId);if(c is null)db.CartItems.Add(new CartItem{UserId=t.Id,ProductId=req.ProductId,Qty=req.Qty});else{if(c.Qty+req.Qty>p.Stock)return BadRequest(new{error="Not enough stock"});c.Qty+=req.Qty;}await db.SaveChangesAsync();return StatusCode(201,new{message="Added to cart"});}
 [HttpDelete("{productId:int}")]public async Task<IActionResult> Delete(int productId,[FromServices]AppDbContext db){var r=RequireUser(out var t);if(r is not null)return r;var c=await db.CartItems.FirstOrDefaultAsync(x=>x.UserId==t!.Id&&x.ProductId==productId);if(c is null)return NotFound();db.CartItems.Remove(c);await db.SaveChangesAsync();return NoContent();}
}
